
const express = require("express");
const { randomUUID } = require("crypto");

const { getGraph } = require("../graph/client");
const { runInvestigation } = require("../agents/investigationAgent");
const authenticate = require("../middleware/authenticate");

const router = express.Router();
function isValidUUID(value) {
  return (
    typeof value === "string" &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
      value
    )
  );
}

// Validate standard UUIDs generated by crypto.randomUUID().
function isValidUUID(value) {
  return (
    typeof value === "string" &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
      value
    )
  );
}

// Seed the shared synthetic demo graph.
router.post("/seed", async (req, res) => {
  try {
    const { graph } = await getGraph();

    await graph.query(`
      MERGE (i:Input {id: 'input-demo'})
      SET i.name = 'HTTP request parameter',
          i.trust = 'untrusted'

      MERGE (f:Function {id: 'fn-query-builder'})
      SET f.name = 'buildCustomerQuery'

      MERGE (s:Sink {id: 'sink-sql'})
      SET s.name = 'SQL query execution',
          s.type = 'sql'

      MERGE (a:Asset {id: 'asset-customers'})
      SET a.name = 'Customer database',
          a.sensitivity = 'high'

      MERGE (i)-[:FLOWS_TO]->(f)
      MERGE (f)-[:FLOWS_TO]->(s)
      MERGE (s)-[:AFFECTS]->(a)

      MERGE (si:Input {id: 'input-safe-demo'})
      SET si.name = 'Validated search parameter',
          si.trust = 'validated'

      MERGE (san:Sanitizer {id: 'sanitizer-demo'})
      SET san.name = 'Parameterized query binding'

      MERGE (sf:Function {id: 'fn-safe-query'})
      SET sf.name = 'findCustomerSafely'

      MERGE (ss:Sink {id: 'sink-safe-sql'})
      SET ss.name = 'Parameterized SQL execution',
          ss.type = 'sql'

      MERGE (si)-[:FLOWS_TO]->(san)
      MERGE (san)-[:FLOWS_TO]->(sf)
      MERGE (sf)-[:FLOWS_TO]->(ss)

      RETURN 'seeded' AS status
    `);

    res.json({
      status: "seeded",
      message: "Synthetic vulnerable and safer flows are in the graph.",
    });
  } catch (error) {
    console.error("Seed failed:", error.message);

    res.status(503).json({
      error: "Could not seed graph.",
    });
  }
});

// Run the existing synthetic graph investigation.
router.post("/run", authenticate, async (req, res) => {
  try {
    const { graph } = await getGraph();
    const investigation = await runInvestigation(graph);

    const id = `investigation-${randomUUID()}`;
    const createdAt = new Date().toISOString();
    const userId = String(req.user.id);

    await graph.query(
      `
        CREATE (inv:Investigation {
          id: $id,
          userId: $userId,
          createdAt: $createdAt,
          status: $status,
          finding: $finding
        })
      `,
      {
        params: {
          id,
          userId,
          createdAt,
          status: investigation.status,
          finding: investigation.summary,
        },
      }
    );

    res.json({
      id,
      createdAt,
      ...investigation,
    });
  } catch (error) {
    console.error("Investigation failed:", error.message);

    res.status(503).json({
      error: "Investigation failed.",
      message: "Check backend logs and the FalkorDB connection.",
    });
  }
});

// Investigate one submitted-code scan owned by the signed-in user.
router.post("/scan/:scanId", authenticate, async (req, res) => {
  const scanId = String(req.params.scanId || "");
  const userId = String(req.user.id);

  if (!isValidUUID(scanId)) {
    return res.status(400).json({
      error: "Invalid scan ID.",
    });
  }

  try {
    const { graph } = await getGraph();

    // Find the scan through its owned File node.
    // This also supports scans with zero findings.
    const lookup = await graph.query(
      `
        MATCH (file:File {
          scanId: $scanId,
          ownerId: $userId
        })
        RETURN file.id AS fileId
        LIMIT 1
      `,
      {
        params: {
          scanId,
          userId,
        },
      }
    );

    const fileId = lookup.data?.[0]?.fileId;

    if (!fileId) {
      return res.status(404).json({
        error: "Scan not found.",
        message: "No scan belonging to this account was found.",
      });
    }

    // Retrieve only evidence belonging to this scan and user.
    const investigation = await runInvestigation(graph, {
      scanId,
      userId,
      fileId,
    });

    const id = `investigation-${randomUUID()}`;
    const createdAt = new Date().toISOString();

    // Persist the investigation for this user and scan.
    await graph.query(
      `
        CREATE (inv:Investigation {
          id: $id,
          userId: $userId,
          scanId: $scanId,
          fileId: $fileId,
          createdAt: $createdAt,
          status: $status,
          finding: $finding
        })
      `,
      {
        params: {
          id,
          userId,
          scanId,
          fileId,
          createdAt,
          status: investigation.status,
          finding: investigation.summary,
        },
      }
    );

    return res.json({
      id,
      createdAt,
      scanId,
      fileId,
      ...investigation,
    });
  } catch (error) {
    console.error("Scan investigation failed:", error.message);

    return res.status(503).json({
      error: "Scan investigation failed.",
      message: "Check backend logs and the FalkorDB connection.",
    });
  }
});

// Return only the signed-in user's investigation history.
router.get("/history", authenticate, async (req, res) => {
  try {
    const { graph } = await getGraph();

    const result = await graph.query(
      `
        MATCH (inv:Investigation {userId: $userId})
        RETURN inv.id AS id,
               inv.createdAt AS createdAt,
               inv.status AS status,
               inv.finding AS finding,
               inv.scanId AS scanId
        ORDER BY inv.createdAt DESC
        LIMIT 20
      `,
      {
        params: {
          userId: String(req.user.id),
        },
      }
    );

    res.json({
      investigations: result.data || [],
    });
  } catch (error) {
    console.error("History lookup failed:", error.message);

    res.status(503).json({
      error: "Could not retrieve investigation history.",
    });
  }
});

// Compare the shared synthetic vulnerable and safer flows.
router.get("/compare", async (req, res) => {
  try {
    const { graph } = await getGraph();

    const vulnerable = await graph.query(`
      MATCH (i:Input {id: 'input-demo'})
            -[:FLOWS_TO]->(f:Function)
            -[:FLOWS_TO]->(s:Sink)
            -[:AFFECTS]->(a:Asset)
      RETURN i.name AS input,
             i.trust AS trust,
             f.name AS function,
             s.name AS sink,
             a.name AS asset,
             a.sensitivity AS sensitivity
    `);

    const safer = await graph.query(`
      MATCH (i:Input {id: 'input-safe-demo'})
            -[:FLOWS_TO]->(san:Sanitizer)
            -[:FLOWS_TO]->(f:Function)
            -[:FLOWS_TO]->(s:Sink)
      RETURN i.name AS input,
             i.trust AS trust,
             san.name AS protection,
             f.name AS function,
             s.name AS sink
    `);

    return res.json({
      vulnerableFlow: vulnerable.data || [],
      saferFlow: safer.data || [],
      note: "Synthetic graph comparison, not proof of source-code exploitability.",
    });
  } catch (error) {
    console.error("Flow comparison failed:", error.message);

    return res.status(503).json({
      error: "Could not compare flows.",
    });
  }
});

// Blast radius of the shared synthetic vulnerable flow.
router.get("/blast-radius", async (req, res) => {
  try {
    const { graph } = await getGraph();

    const result = await graph.query(`
      MATCH (i:Input {id: 'input-demo'})
            -[:FLOWS_TO*1..6]->(sink:Sink)
            -[:AFFECTS]->(asset:Asset)
      RETURN DISTINCT
        i.name AS source,
        sink.name AS sink,
        asset.id AS assetId,
        asset.name AS asset,
        asset.sensitivity AS sensitivity
      ORDER BY asset.name
    `);

    const assets = result.data || [];

    return res.json({
      count: assets.length,
      assets,
      explanation: assets.length
        ? "The graph contains a reachable sensitive asset along the modeled input-to-sink path."
        : "No matching asset path was found in the analyzed graph.",
      limitation:
        "Results reflect modeled graph relationships, not proof of runtime exploitability.",
    });
  } catch (error) {
    console.error("Blast-radius analysis failed:", error.message);

    return res.status(503).json({
      error: "Blast-radius analysis failed.",
    });
  }
});

module.exports = router;
